def pick_boxy_object_top_down_by_pose_and_points(object_names, approach_height=0.12, lift_height=0.12, top_clearance=0.005, use_multiview=True):
    import numpy as np
    if isinstance(object_names, str):
        object_names = [object_names]

    center = None
    quat = None
    used_name = None
    for name in object_names:
        pos, q = get_object_pose(name, use_multiview=use_multiview)
