    if used_name is not None:
        try:
            seg = get_object_3d_points_and_masks_from_language(used_name.replace('_', ' '), use_multiview=use_multiview)
            pts = seg.get('points_3d', None)
            if pts is not None and len(pts) >= 10:
                points = np.array(pts, dtype=float)
        except Exception:
            points = None

    if center is None:
        for name in object_names:
            try:
                seg = get_object_3d_points_and_masks_from_language(name.replace('_', ' '), use_multiview=use_multiview)
                pts = seg.get('points_3d', None)
                if pts is not None and len(pts) >= 10:
                    points = np.array(pts, dtype=float)
                    center = np.median(points, axis=0)
                    used_name = name
                    break
            except Exception:
                continue

    if center is None:
        return {'success': False, 'error': 'could_not_localize_object', 'object_name': None}

    if points is not None and len(points) >= 10:
        xy = np.median(points[:, :2], axis=0)
        top_z = float(np.percentile(points[:, 2], 95))
    else:
        xy = center[:2]
        top_z = float(center[2] + 0.025)

    down_quat = np.array([0.0, 0.0, 1.0, 0.0], dtype=float)
    grasp_position = np.array([xy[0], xy[1], top_z + float(top_clearance)], dtype=float)
    lift_position = grasp_position + np.array([0.0, 0.0, float(lift_height)], dtype=float)

    open_gripper()
    goto_pose(grasp_position, down_quat, z_approach=float(approach_height))
    close_gripper()
    goto_pose(lift_position, down_quat, z_approach=0.0)

