        'gripper_value_after_close': gripper_value
    }

def pull_engaged_drawer_handle_until_open(handle_position, handle_quaternion, interior_prompt='open top drawer interior', pull_distances=(0.18, 0.32, 0.46), min_interior_points=30, release_on_success=True):
    import numpy as np
    if handle_position is None or handle_quaternion is None:
        return {'success': False, 'interior_center': None, 'points_count': 0}

    start = np.array(handle_position, dtype=float)
    q = np.array(handle_quaternion, dtype=float)
    q = q / max(np.linalg.norm(q), 1e-9)

    for d in pull_distances:
        target = start + np.array([0.0, -float(d), 0.0], dtype=float)
        goto_pose(target, q, z_approach=0.0)
        obs = get_observation()
        width = float(obs['robot_cartesian_pos'][-1])
        if width < 0.005:
            return {'success': False, 'interior_center': None, 'points_count': 0, 'reason': 'lost_handle_grasp'}

        try:
            seg = get_object_3d_points_and_masks_from_language(interior_prompt, use_multiview=True)
            pts = seg.get('points_3d', None)
            n = 0 if pts is None else int(len(pts))
            if pts is not None and n >= min_interior_points:
                center = np.mean(pts, axis=0)
                if release_on_success:
                    open_gripper()
                    goto_pose(target + np.array([0.0, -0.06, 0.08], dtype=float), q, z_approach=0.0)
                return {'success': True, 'interior_center': center, 'points_count': n}
        except Exception:
            pass

    final_target = start + np.array([0.0, -float(pull_distances[-1]), 0.0], dtype=float)
    if release_on_success:
        open_gripper()
        goto_pose(final_target + np.array([0.0, -0.06, 0.08], dtype=float), q, z_approach=0.0)
    return {'success': False, 'interior_center': None, 'points_count': 0}

