def pick_yellow_moka_pot_with_filtered_sample_or_neck_grasp(object_prompt='yellow moka pot', pose_names=('yellow_moka_pot',), max_samples=5, min_xy_offset=0.04, approach_height=0.18, lift_height=0.18, fallback_height_fraction=0.85, use_multiview=True, verify_with_wrist_color=True, color_thresholds=None):
    import numpy as np

    def _quat_to_rot_wxyz(q):
        q = np.asarray(q, dtype=float)
        n = np.linalg.norm(q)
        if n < 1e-8:
            return np.eye(3)
        w, x, y, z = q / n
        return np.array([[1-2*y*y-2*z*z, 2*x*y-2*z*w, 2*x*z+2*y*w], [2*x*y+2*z*w, 1-2*x*x-2*z*z, 2*y*z-2*x*w], [2*x*z-2*y*w, 2*y*z+2*x*w, 1-2*x*x-2*y*y]], dtype=float)

    def _held_signal():
        obs = get_observation()
        grip = float(obs['robot_cartesian_pos'][-1])
        frac = 0.0
        if verify_with_wrist_color:
            th = color_thresholds or {'r_min': 90.0, 'g_min': 70.0, 'b_max': 130.0, 'rg_over_b': 1.55}
            rgb = obs['robot0_eye_in_hand']['images']['rgb'].astype(np.float32)
            r, g, b = rgb[:, :, 0], rgb[:, :, 1], rgb[:, :, 2]
            mask = (r > th['r_min']) & (g > th['g_min']) & (b < th['b_max']) & ((r + g) > th['rg_over_b'] * (b + 1.0))
            frac = float(np.mean(mask))
        return grip, frac

    if isinstance(pose_names, str):
        pose_names = (pose_names,)
    seg = get_object_3d_points_and_masks_from_language(object_prompt, use_multiview=use_multiview)
    pts = seg.get('points_3d', None) if seg is not None else None
    center = None
    if pts is not None and len(pts) >= 20:
        pts = np.asarray(pts, dtype=float)
        center = np.mean(pts, axis=0)
        z_min, z_max = float(np.min(pts[:, 2])), float(np.max(pts[:, 2]))
    else:
        for name in pose_names:
            p, _ = get_object_pose(name, use_multiview=use_multiview)
            if p is not None:
                center = np.asarray(p, dtype=float)
                break
        if center is None:
            return {'success': False, 'error': 'could_not_localize_object', 'object_prompt': object_prompt}
        z_min, z_max = center[2] - 0.04, center[2] + 0.12

    attempts = []
    for i in range(int(max_samples)):
        try:
            gp, gq = sample_grasp_pose(object_prompt, use_multiview=use_multiview)
        except Exception as e:
            attempts.append({'strategy': 'filtered_sample', 'sample_index': i, 'error': str(e)})
            continue
        if gp is None or gq is None:
            continue
        gp, gq = np.asarray(gp, dtype=float), np.asarray(gq, dtype=float)
        xy_offset = float(np.linalg.norm(gp[:2] - center[:2]))
        horizontal_score = float(np.linalg.norm(_quat_to_rot_wxyz(gq)[:, 2][:2]))
        accepted = xy_offset >= float(min_xy_offset) and horizontal_score >= 0.866
        attempts.append({'strategy': 'filtered_sample', 'sample_index': i, 'xy_offset': xy_offset, 'horizontal_score': horizontal_score, 'accepted': bool(accepted)})
        if accepted:
            open_gripper(); goto_pose(gp, gq, z_approach=float(approach_height)); close_gripper()
            lift_pos = gp.copy(); lift_pos[2] += float(lift_height); goto_pose(lift_pos, gq, z_approach=0.0)
            grip, frac = _held_signal()
            if grip > 0.02 or frac > 0.20:
                return {'success': True, 'strategy': 'filtered_sample', 'grasp_position': gp, 'grasp_quaternion': gq, 'lift_position': lift_pos, 'gripper_position': grip, 'wrist_color_fraction': frac, 'attempts': attempts}

    fallback_pos = np.array([center[0], center[1], z_min + float(fallback_height_fraction) * (z_max - z_min)], dtype=float)
    fallback_quat = np.array([0.0, 1.0, 0.0, 0.0], dtype=float)
    open_gripper(); goto_pose(fallback_pos, fallback_quat, z_approach=float(approach_height)); close_gripper()
    lift_pos = fallback_pos.copy(); lift_pos[2] += float(lift_height); goto_pose(lift_pos, fallback_quat, z_approach=0.0)
    grip, frac = _held_signal()
    return {'success': bool(grip > 0.02 or frac > 0.20), 'strategy': 'upper_part_fallback', 'grasp_position': fallback_pos, 'grasp_quaternion': fallback_quat, 'lift_position': lift_pos, 'gripper_position': grip, 'wrist_color_fraction': frac, 'attempts': attempts}

def verify_yellow_object_held_after_lift(min_gripper_position=0.02, min_color_fraction=0.20, color_name='yellow', color_thresholds=None):
    import numpy as np
    obs = get_observation()
    gripper_position = float(obs['robot_cartesian_pos'][-1])
    wrist_rgb = obs['robot0_eye_in_hand']['images']['rgb'].astype(np.float32)
    r = wrist_rgb[:, :, 0]
    g = wrist_rgb[:, :, 1]
    b = wrist_rgb[:, :, 2]

    presets = {
        'yellow': {'r_min': 90.0, 'g_min': 70.0, 'b_max': 130.0, 'rg_over_b': 1.55, 'max_rg_diff': 100.0},
        'red': {'r_min': 100.0, 'g_max': 120.0, 'b_max': 120.0, 'r_over_gb': 1.25},
        'orange': {'r_min': 100.0, 'g_min': 45.0, 'g_max': 170.0, 'b_max': 120.0, 'r_over_b': 1.4},
        'dark': {'sum_max': 180.0},
        'white': {'r_min': 170.0, 'g_min': 170.0, 'b_min': 170.0},
    }
    th = color_thresholds if color_thresholds is not None else presets.get(color_name, presets['yellow'])

    if 'sum_max' in th:
        mask = (r + g + b) < float(th['sum_max'])
    elif 'r_over_gb' in th:
        mask = (r > th['r_min']) & (g < th['g_max']) & (b < th['b_max']) & (r > th['r_over_gb'] * (g + b + 1.0) / 2.0)
    elif 'r_over_b' in th:
        mask = (r > th['r_min']) & (g > th['g_min']) & (g < th['g_max']) & (b < th['b_max']) & (r > th['r_over_b'] * (b + 1.0))
    elif 'b_min' in th:
        mask = (r > th['r_min']) & (g > th['g_min']) & (b > th['b_min'])
    else:
        mask = (r > th['r_min']) & (g > th['g_min']) & (b < th['b_max']) & ((r + g) > th['rg_over_b'] * (b + 1.0))
        if 'max_rg_diff' in th:
            mask = mask & (np.abs(r - g) < th['max_rg_diff'])

    color_fraction = float(np.mean(mask))
    held = bool((gripper_position > float(min_gripper_position)) or (color_fraction > float(min_color_fraction)))
    return {'held': held, 'gripper_position': gripper_position, 'wrist_color_fraction': color_fraction, 'color_name': color_name}

def compute_fixture_layer_place_center_from_z_clusters(fixture_prompt, layer_index=0, object_half_height=0.03, min_points=80, z_bin_size=0.015, use_multiview=True, xy_statistic='median'):
    import numpy as np
    seg = get_object_3d_points_and_masks_from_language(fixture_prompt, use_multiview=use_multiview)
    pts = seg.get('points_3d', None) if seg is not None else None
    if pts is None:
        raise RuntimeError('No fixture points found')
    pts = np.asarray(pts, dtype=float)
    pts = pts[np.isfinite(pts).all(axis=1)]
    if len(pts) < int(min_points):
        raise RuntimeError('Too few fixture points found')

    z = pts[:, 2]
    z_min = float(np.min(z))
    bins = np.floor((z - z_min) / float(z_bin_size)).astype(int)
    clusters = []
    for b in np.unique(bins):
        band = pts[bins == b]
        if len(band) >= max(10, int(min_points) // 10):
            clusters.append({'z': float(np.median(band[:, 2])), 'count': int(len(band)), 'points': band})
    if not clusters:
        raise RuntimeError('Could not find horizontal z layers for fixture')

    clusters = sorted(clusters, key=lambda c: c['z'])
    merged = []
    for c in clusters:
        if not merged or abs(c['z'] - merged[-1]['z']) > 2.5 * float(z_bin_size):
            merged.append(c)
        else:
            allp = np.vstack([merged[-1]['points'], c['points']])
            merged[-1] = {'z': float(np.median(allp[:, 2])), 'count': int(len(allp)), 'points': allp}

    idx = int(layer_index)
    if idx < 0:
        idx = len(merged) + idx
    idx = max(0, min(idx, len(merged) - 1))
    lp = merged[idx]['points']
    if xy_statistic == 'mean':
        xy = np.mean(lp[:, :2], axis=0)
    else:
        xy = np.median(lp[:, :2], axis=0)
    layer_z = float(np.percentile(lp[:, 2], 90))
    center = np.array([xy[0], xy[1], layer_z + float(object_half_height)], dtype=float)
    return {'center': center, 'layer_z': layer_z, 'layer_index': idx, 'num_layers': int(len(merged)), 'num_points': int(len(lp)), 'score': seg.get('agentview_score', None) if seg is not None else None, 'use_multiview': use_multiview}

def pick_object_with_prompt_aliases_sample_or_pose_topdown(object_prompts, approach_height=0.12, lift_height=0.16, pose_z_offset=0.0, use_multiview_options=(True, False)):
    import numpy as np
    if isinstance(object_prompts, str):
        object_prompts = [object_prompts]
    errors = []
    open_gripper()

    for use_mv in use_multiview_options:
        for prompt in object_prompts:
            try:
                pos, quat = sample_grasp_pose(prompt, use_multiview=use_mv)
                if pos is None or quat is None:
                    errors.append((prompt, use_mv, 'sample returned None'))
                    continue
                pos = np.asarray(pos, dtype=float).copy()
                quat = np.asarray(quat, dtype=float).copy()
                goto_pose(pos, quat, z_approach=approach_height)
                close_gripper()
                lift_pos = pos.copy()
                lift_pos[2] += float(lift_height)
                goto_pose(lift_pos, quat)
                return {'success': True, 'prompt': prompt, 'use_multiview': use_mv, 'strategy': 'sample_grasp', 'position': lift_pos, 'quaternion': quat, 'errors': errors}
            except Exception as e:
                errors.append((prompt, use_mv, str(e)))

    topdown_quat = np.array([0.0, 0.0, 1.0, 0.0], dtype=float)
    for use_mv in use_multiview_options:
        for prompt in object_prompts:
            try:
                pos, _ = get_object_pose(prompt, use_multiview=use_mv)
                if pos is None:
                    errors.append((prompt, use_mv, 'pose returned None'))
                    continue
                pos = np.asarray(pos, dtype=float).copy()
                pos[2] += float(pose_z_offset)
                goto_pose(pos, topdown_quat, z_approach=approach_height)
                close_gripper()
                lift_pos = pos.copy()
                lift_pos[2] += float(lift_height)
                goto_pose(lift_pos, topdown_quat)
                return {'success': True, 'prompt': prompt, 'use_multiview': use_mv, 'strategy': 'pose_topdown_fallback', 'position': lift_pos, 'quaternion': topdown_quat, 'errors': errors}
            except Exception as e:
                errors.append((prompt, use_mv, str(e)))

    return {'success': False, 'prompt': None, 'use_multiview': None, 'strategy': None, 'position': None, 'quaternion': None, 'errors': errors}

def pick_object_top_neck_from_segmentation_top_fraction(prompt='yellow moka pot', top_fraction=0.15, lift_height=0.18, approach_clearance=0.18):
    import numpy as np
    seg = get_object_3d_points_and_masks_from_language(prompt, use_multiview=True)
    pts = seg.get('points_3d', None)
    if pts is None or len(pts) < 30:
        return {'success': False, 'error': 'segmentation_insufficient'}
    z = pts[:, 2]
    z_min = float(np.min(z)); z_max = float(np.max(z)); h = z_max - z_min
    if h < 1e-3:
        return {'success': False, 'error': 'flat_segmentation'}
    cutoff = z_min + (1.0 - top_fraction) * h
    upper = pts[z >= cutoff]
    if len(upper) < 10:
        upper = pts[z >= z_min + 0.85 * h]
    if len(upper) < 5:
        return {'success': False, 'error': 'no_upper_points'}
    grasp_xy = np.mean(upper[:, :2], axis=0)
    grasp_z = z_min + 0.88 * h
    grasp_pos = np.array([grasp_xy[0], grasp_xy[1], grasp_z])
    quat = np.array([0.0, 1.0, 0.0, 0.0])
    open_gripper()
    goto_pose(grasp_pos, quat, z_approach=approach_clearance)
    close_gripper()
    lifted = grasp_pos.copy(); lifted[2] += lift_height
    goto_pose(lifted, quat, z_approach=0.0)
    return {'success': True, 'grasp_position': grasp_pos, 'grasp_quaternion': quat, 'lifted_position': lifted, 'upper_points_count': int(len(upper))}

def verify_grasp_and_lift_via_robot_state(expected_min_z, min_gripper_norm=0.02, max_gripper_norm=0.9):
    try:
        obs = get_observation()
        ee = obs["robot_cartesian_pos"]
        gripper_norm = float(ee[7])
        ee_z = float(ee[2])
        is_lifted = ee_z > expected_min_z
        is_holding = min_gripper_norm < gripper_norm < max_gripper_norm
        success = is_lifted
        return {"is_lifted": is_lifted, "is_holding": is_holding, "success": success, "ee_z": ee_z, "gripper_norm": gripper_norm}
    except Exception as e:
        return {"success": False, "error": str(e)}
